def choose_move(observation):
    g = observation if isinstance(observation, dict) else {}

    def iv(x, d=0):
        try:
            return int(x)
        except Exception:
            return d

    def pos(v, d=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return (iv(v[0], d[0]), iv(v[1], d[1]))
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                return (iv(v.get("x"), d[0]), iv(v.get("y"), d[1]))
        return d

    def seq(v):
        return v if isinstance(v, (list, tuple)) else []

    def aset(v):
        out = set()
        for x in seq(v):
            out.add(pos(x))
        return out

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    w = iv(g.get("grid_width", g.get("width", 0)), 0)
    h = iv(g.get("grid_height", g.get("height", 0)), 0)

    s = pos(g.get("self_position", g.get("agent_position", g.get("position"))))
    o = pos(g.get("opponent_position", g.get("enemy_position", g.get("target_position", (-999, -999)))))

    resources = [pos(x) for x in seq(g.get("resources", g.get("resource_positions", [])))]
    obstacles = aset(g.get("obstacles", g.get("walls", [])))
    self_path = aset(g.get("self_path", g.get("trail", [])))
    opp_path = aset(g.get("opponent_path", g.get("enemy_path", [])))

    my_territory = aset(g.get("self_territory", g.get("territory", g.get("owned_cells", []))))
    opp_territory = aset(g.get("opponent_territory", g.get("enemy_territory", [])))

    home = pos(g.get("home_position", g.get("base_position", g.get("spawn_position", s))))
    opp_home = pos(g.get("opponent_home", g.get("enemy_base", o)))

    carry = iv(g.get("carrying", g.get("carry", g.get("resource_count", 0))), 0)
    max_carry = iv(g.get("capacity", g.get("max_carry", 0)), 0)

    def valid(p):
        if w > 0 and not (0 <= p[0] < w):
            return False
        if h > 0 and not (0 <= p[1] < h):
            return False
        return p not in obstacles

    def nearest(ps, p):
        best = None
        bd = None
        for q in ps:
            d = dist(p, q)
            if bd is None or d < bd:
                bd = d
                best = q
        return best, bd if bd is not None else 10**9

    mode = "territory"
